import React, { useEffect } from 'react';

import { Cover, TemplateSlide } from 'components';
import DOMPurify from 'dompurify';
import { usePageIndexes } from 'hooks';
import {
  CountrySlide,
  EvolutionSlide,
} from 'pages/components/PortfolioBrand/Slides';
import type { CountryExportData } from 'redux/api/bff';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import {
  StyledContent,
  StyledParagraph,
} from '../../../BrandPowerBookExport.styles';
import {
  EXECUTIVE_SUMMARY_INSIGHTS_CONFIG,
  EXPORT_COUNTRIES,
  type ExportCountry,
  getCountrySlideId,
} from '../../../constants';
import { findInsightTexts } from '../../../helpers';
import type { AllCountriesData } from '../../../hooks/useAllCountriesData';
import { InsightRecord } from '../../../types';
import { InsightsSlide } from '../../InsightsSlide';
import { LazySlide } from '../../LazySlide';
import { SubCover } from '../../SubCover/SubCover';
import { buildCountrySlideProps, buildEvolutionInfos } from './utils';

export { getCountrySlideId } from '../../../constants';

interface CountryInlineViewProps {
  containerRef: React.RefObject<HTMLElement>;
  countriesData: AllCountriesData;
  loading: boolean;
  qtdPeriod: string;
  ytdPeriod: string;
  ytdSubCoverLabel: string;
  qtdCoverPrefix: string;
  coverPeriod: React.ReactNode;
  insightsData: InsightRecord[];
}

interface PerformanceSlideParams {
  country: ExportCountry;
  data: CountryExportData | undefined;
  label: string;
  titlePrefix: string;
  period: 'qtd' | 'ytd';
  isCompetitor: boolean;
  loading: boolean;
  page?: number;
  insightsData: InsightRecord[];
}

interface ExecutiveSummarySlide {
  country: ExportCountry;
  label: string;
  period: 'qtd' | 'ytd';
  page?: number;
  insightsData: InsightRecord[];
}

const renderCountryCover = (
  country: ExportCountry,
  coverPeriod: React.ReactNode,
) => {
  const slideId = getCountrySlideId(country.code, 'cover');
  return (
    <LazySlide key={slideId} id={slideId}>
      <StyledExportPageSection data-page-name={slideId}>
        <Cover
          name="Brand Power Book"
          countries={[{ code: country.code, name: country.name }]}
          loading={false}
          period={coverPeriod}
          showLogo
        />
      </StyledExportPageSection>
    </LazySlide>
  );
};

const renderEvolution = (
  country: ExportCountry,
  data: CountryExportData | undefined,
  qtdPeriod: string,
  loading: boolean,
  insightsData: InsightRecord[],
  page: number,
) => {
  const slideId = getCountrySlideId(country.code, 'qtd-evolution');
  const isLoading = loading || !data;

  return (
    <LazySlide key={slideId} id={slideId}>
      <StyledExportPageSection data-page-name={slideId}>
        <TemplateSlide
          enablePngCopy
          title={`${country.name} ABI: Power Evolution`}
          period={qtdPeriod}
          footnotes={
            country.code === 'DOM' ? (
              <>
                <b>About results:</b> Results before 2022 exclude the Dominican
                Republic in the survey.
              </>
            ) : undefined
          }
          page={page}
          countryId={country.code}
          headerDivider={false}
          dataTestId={slideId}
        >
          <StyledContent>
            <EvolutionSlide
              evolutionSlideInfos={buildEvolutionInfos(
                data?.overview,
                data?.overviewMegabrands,
                isLoading,
              )}
              alerts={findInsightTexts(insightsData, {
                type: 'Country',
                country: country.code,
                template: 'Evolution',
                scope: 'None',
                sub_scope: 'None',
                segmented_control: 'None',
                timeframe: 'QTD',
              })}
              dataTestId={`slide-evolution-${country.code.toLowerCase()}`}
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>
    </LazySlide>
  );
};

const renderSubCover = (
  country: ExportCountry,
  periodLabel: string,
  period: 'qtd' | 'ytd',
) => {
  const slideId = getCountrySlideId(country.code, `${period}-cover`);
  return (
    <LazySlide key={slideId} id={slideId}>
      <StyledExportPageSection data-page-name={slideId}>
        <SubCover
          title={periodLabel}
          countryCode={country.code}
          countryName={country.name}
        />
      </StyledExportPageSection>
    </LazySlide>
  );
};

const renderPerformanceSlide = ({
  country,
  data,
  label,
  titlePrefix,
  period,
  isCompetitor,
  loading,
  page,
  insightsData,
}: PerformanceSlideParams) => {
  const suffix = isCompetitor ? 'competitor' : 'abi';
  const slideId = getCountrySlideId(country.code, `${period}-${suffix}`);
  const isLoading = loading || !data;

  return (
    <LazySlide key={slideId} id={slideId}>
      <StyledExportPageSection data-page-name={slideId}>
        <TemplateSlide
          enablePngCopy
          title={`${country.name} ${isCompetitor ? 'Competition' : 'ABI'}: ${titlePrefix} Performance`}
          period={label}
          footnotes=""
          page={page}
          countryId={country.code}
          headerDivider={false}
          dataTestId={slideId}
        >
          <StyledContent>
            <CountrySlide
              {...buildCountrySlideProps(data, isCompetitor)}
              loading={isLoading}
              error={null}
              alerts={findInsightTexts(insightsData, {
                type: 'Country',
                scope: 'None',
                template: 'Brands',
                sub_scope: 'None',
                segmented_control: isCompetitor ? 'Competitor' : 'ABI',
                timeframe: period === 'qtd' ? 'QTD' : 'YTD',
                country: country.code,
              })}
              dataTestId={`slide-${slideId}`}
            />
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>
    </LazySlide>
  );
};

const renderExecutiveSummarySlide = ({
  country,
  label,
  period,
  page,
  insightsData,
}: ExecutiveSummarySlide) => {
  const timeframe = period === 'qtd' ? 'QTD' : 'YTD';
  const slideId = getCountrySlideId(
    country.code,
    `${period}-executive-summary`,
  );

  const insights = insightsData
    ?.filter(
      (insight) =>
        insight.type === 'Country' &&
        insight.template === 'Executive Summary' &&
        insight.country === country.code &&
        !!insight.insight_text &&
        insight.insights_title !== 'None' &&
        insight.timeframe === timeframe,
    )
    .sort(
      (a, b) =>
        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[a.insights_title].indexBadge -
        EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[b.insights_title].indexBadge,
    );

  if (!insights || insights.length === 0) {
    return null;
  }

  return (
    <LazySlide key={slideId} id={slideId}>
      <StyledExportPageSection data-page-name={slideId}>
        <TemplateSlide
          enablePngCopy
          title="Executive Summary"
          period={label}
          page={page}
          countryId="ABI"
          headerDivider={false}
          dataTestId={slideId}
        >
          <StyledContent $hasSpacing>
            {insights.map(
              (insight) =>
                !!insight.insight_text && (
                  <InsightsSlide
                    key={insight.insights_title}
                    title={
                      EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[insight.insights_title]
                        .title
                    }
                    content={(insight.insight_text.split('\n') ?? []).map(
                      (alert, index) => (
                        <StyledParagraph
                          key={alert + index}
                          dangerouslySetInnerHTML={{
                            __html: DOMPurify.sanitize(alert),
                          }}
                        />
                      ),
                    )}
                    indexBadge={
                      EXECUTIVE_SUMMARY_INSIGHTS_CONFIG[insight.insights_title]
                        .indexBadge
                    }
                  />
                ),
            )}
          </StyledContent>
        </TemplateSlide>
      </StyledExportPageSection>
    </LazySlide>
  );
};

export const CountryInlineView: React.FC<CountryInlineViewProps> = ({
  containerRef,
  countriesData,
  loading,
  qtdPeriod,
  ytdPeriod,
  ytdSubCoverLabel,
  qtdCoverPrefix,
  coverPeriod,
  insightsData,
}) => {
  const { getPageByName, updateIndexes } = usePageIndexes(containerRef);

  useEffect(() => {
    updateIndexes();
  }, [updateIndexes]);

  const getPage = (code: string, suffix: string) =>
    getPageByName(getCountrySlideId(code, suffix))?.index;

  const renderCountry = (country: ExportCountry) => {
    const qtdData = countriesData.QTD[country.code];
    const ytdData = countriesData.YTD[country.code];

    return (
      <React.Fragment key={country.code}>
        {renderCountryCover(country, coverPeriod)}
        {renderExecutiveSummarySlide({
          country,
          label: qtdPeriod,
          period: 'qtd',
          page: getPage(country.code, 'qtd-executive-summary'),
          insightsData,
        })}
        {country.hasFullSlides &&
          renderEvolution(
            country,
            qtdData,
            qtdPeriod,
            loading,
            insightsData,
            getPage(country.code, 'qtd-evolution'),
          )}
        {renderSubCover(country, qtdPeriod, 'qtd')}
        {renderPerformanceSlide({
          country,
          data: qtdData,
          label: qtdPeriod,
          titlePrefix: qtdCoverPrefix,
          period: 'qtd',
          isCompetitor: false,
          loading,
          page: getPage(country.code, 'qtd-abi'),
          insightsData,
        })}
        {renderPerformanceSlide({
          country,
          data: qtdData,
          label: qtdPeriod,
          titlePrefix: qtdCoverPrefix,
          period: 'qtd',
          isCompetitor: true,
          loading,
          page: getPage(country.code, 'qtd-competitor'),
          insightsData,
        })}
        {renderSubCover(country, ytdSubCoverLabel, 'ytd')}
        {renderExecutiveSummarySlide({
          country,
          label: ytdPeriod,
          period: 'ytd',
          page: getPage(country.code, 'ytd-executive-summary'),
          insightsData,
        })}
        {renderPerformanceSlide({
          country,
          data: ytdData,
          label: ytdPeriod,
          titlePrefix: 'YTD',
          period: 'ytd',
          isCompetitor: false,
          loading,
          page: getPage(country.code, 'ytd-abi'),
          insightsData,
        })}
        {renderPerformanceSlide({
          country,
          data: ytdData,
          label: ytdPeriod,
          titlePrefix: 'YTD',
          period: 'ytd',
          isCompetitor: true,
          loading,
          page: getPage(country.code, 'ytd-competitor'),
          insightsData,
        })}
      </React.Fragment>
    );
  };

  return <>{EXPORT_COUNTRIES.map(renderCountry)}</>;
};
